style.css:
@-moz-document url("https://actualfreedom.com.au/") {
/* 2. Force the body to a solid white background for readability */
body {
    background-color: transparent;
    background: none;
    line-height: 1.6;
    zoom: 110%;
}

/* 3. Handle specific HTML elements often used for layout on this site */
table, tr, td, th, div, span, p, blockquote {
    background: none;
    background-color: transparent;
    font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif !important;
}


h1 font {
    font-size: 0.4em;
    display: none;
}
}
